      return '--- Client-streaming stream passed to service implementations.\n'
        + 'local ' + t + ' = {}\n' + t + '.__index = ' + t + '\n\n'
        + 'function ' + t + '.new(reqs)\n'
        + '  return setmetatable({ reqs = reqs, resp = nil }, ' + t + ')\nend\n\n'
        + 'function ' + t + ':recv()\n'
